                    tasks['pick_heat_then_place'] += 1
                elif 'look at' in task:
                    tasks['look_at_obj_in_light'] += 1
                elif 'put' in task or 'place' in task:
                    tasks['pick_and_place'] += 1
                else:
                    tasks['other'] += 1
                break
total = sum(tasks.values())
print(f'Total trajectories with task: {total}')
